function invalidClipboard() {
  throw new Error(
    'Clipboard must contain an HTTP(S) URL / 剪贴板必须包含 HTTP(S) URL'
  );
}

function escapeMarkdown(text, characters) {
  const slash = String.fromCharCode(92);
  let escaped = '';
  for (const character of text) {
    escaped +=
      character === slash || characters.includes(character)
        ? slash + character
        : character;
  }
  return escaped;
}

function process(data) {
  const text = data && data.selection;
  if (typeof text !== 'string') {
    throw new TypeError('selection must be a string');
  }

  const clipboard = data && data.clipboard;
  if (typeof clipboard !== 'string') {
    invalidClipboard();
  }

  const target = clipboard.trim();
  const lowerTarget = target.toLowerCase();
  if (!lowerTarget.startsWith('http://') && !lowerTarget.startsWith('https://')) {
    invalidClipboard();
  }
  for (const character of target) {
    const code = character.charCodeAt(0);
    if (code <= 31 || code === 127) {
      invalidClipboard();
    }
  }

  let url;
  try {
    url = new URL(target);
  } catch {
    invalidClipboard();
  }
  if ((url.protocol !== 'http:' && url.protocol !== 'https:') || !url.hostname) {
    invalidClipboard();
  }

  const label = escapeMarkdown(text, '[]');
  const destination = escapeMarkdown(url.href, '()');
  return `[${label}](${destination})`;
}
